name: PR Status Labeler
on:
  workflow_run:
    workflows:
      - Capture PR Data
    types:
      - completed

jobs:
  label-pr:
    if: github.event.workflow_run.conclusion == 'success'
    runs-on: ubuntu-latest
    steps:
      - name: Checkout
        uses: actions/checkout@v4

      - name: Get PR data
        id: get_pr_data
        run: |
          PR_NUMBER=${{ github.event.workflow_run.pull_requests[0].number }}
          echo "pr_number=$PR_NUMBER" >> $GITHUB_ENV

      - name: Label PR
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { pr_number } = process.env;

            // Get PR information
            const pr = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: parseInt(pr_number)
            });

            const labels = [];

            // Add labels based on PR content
            if (pr.data.title.toLowerCase().includes('[wip]')) {
              labels.push('work-in-progress');
            }

            if (pr.data.title.toLowerCase().includes('[do not merge]')) {
              labels.push('do-not-merge');
            }

            // Check for changes in specific directories
            const changedFiles = await github.rest.pulls.listFiles({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: parseInt(pr_number)
            });

            const hasPythonChanges = changedFiles.data.some(file => 
              file.filename.endsWith('.py')
            );

            if (hasPythonChanges) {
              labels.push('python');
            }

            const hasDockerfileChanges = changedFiles.data.some(file => 
              file.filename.includes('Dockerfile') || file.filename.includes('dockerfile')
            );

            if (hasDockerfileChanges) {
              labels.push('docker');
            }

            // Remove existing labels that would be added again
            const currentLabels = pr.data.labels.map(label => label.name);
            const labelsToRemove = currentLabels.filter(label => 
              ['work-in-progress', 'do-not-merge', 'python', 'docker'].includes(label)
            );

            // Remove old labels
            for (const label of labelsToRemove) {
              try {
                await github.rest.issues.removeLabel({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: parseInt(pr_number),
                  name: label
                });
              } catch (error) {
                console.log(`Failed to remove label ${label}:`, error.message);
              }
            }

            // Add new labels
            for (const label of labels) {
              try {
                await github.rest.issues.addLabels({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: parseInt(pr_number),
                  labels: [label]
                });
              } catch (error) {
                console.log(`Failed to add label ${label}:`, error.message);
              }
            }
